<?php require __DIR__.'/app/core.php'; $slug=$_GET['slug']??''; $post=null; foreach(posts_all() as $p){ if(($p['slug']??'')===$slug){$post=$p; break;}} if(!$post){http_response_code(404); header_html('blog',['title'=>'Yazı bulunamadı','desc'=>'Yazı bulunamadı']); echo '<section class="section"><div class="wrap article"><h1>Yazı bulunamadı</h1><p class="muted">Aradığınız içerik kaldırılmış olabilir. <a class="post-more" href="/blog">Blog’a dön →</a></p></div></section>'; footer_html(); exit;} header_html('blog',['title'=>$post['title'].' | Xtanbul Yazılım Agent','desc'=>$post['summary']]); ?><section class="section"><article class="wrap article"><span class="eyebrow"><?= ($post['type']??'blog')==='haber'?'Haber':'Blog / Rehber' ?></span><h1><?=e($post['title'])?></h1><p class="lead"><?=e($post['summary'])?></p><small><?=e($post['created_at']??'')?></small><div class="content"><?=nl2br(e($post['content']))?></div><p class="mt"><a class="post-more" href="/<?= ($post['type']??'blog')==='haber'?'haberler':'blog' ?>">← Tüm yazılar</a></p></article></section><?php footer_html(); ?>
